/* The Kokumi — lite workshop board
   Self-contained: the teaching screens from the guide and the questions,
   in one deck. Host-only notes are not in this file. */
window.BLOCKS = [

{ id:"B0", n:"0", name:"Where we are",
  intro:"The one page everything else hangs from, and the story in its current words. Read both before we start deciding.",
  reveal:false, mins:2,
  cards:[
    { id:"r-arch", type:"read", kicker:"Where we are", q:"The one-page brand architecture",
      note:"TOUGHLOVE, 16 September 2026. The rows marked open are the ones still undecided — several of them get decided today.", view:"arch", data:{"rows": [["PURPOSE", "To be developed", "open"], ["VISION", "<b>A</b> &mdash; Enable a world where business flows freely.<br><b>B</b> &mdash; Enable a world where finance never stands in the way of business moving forward.", "open"], ["BRAND BELIEF", "Finance should work for business, not the other way around.", "set"], ["MISSION", "To simplify and connect financial operations, removing the friction that holds businesses back.", "set"], ["BUSINESS DEFINITION", "An integrated financial platform for business.", "set"], ["CUSTOMER", "Businesses whose growth and complexity have outgrown fragmented financial solutions.", "set"], ["STRATEGIC TERRITORY", "FLOW", "open"], ["WORKING PROMISE", "KEEP BUSINESS MOVING", "open"], ["WHAT lite DOES", "Remove friction &rarr; Connect &rarr; Simplify", "set"], ["WHAT CUSTOMERS GAIN", "Connected financial operations &rarr; Clarity &rarr; Control &rarr; Confidence", "set"], ["WHAT IT ENABLES", "Flow &rarr; Momentum / Progress", "set"], ["VALUES", "Own the Outcome &middot; One lite &middot; Speak Openly &middot; Adapt with Purpose &middot; Protect Trust", "set"], ["PERSONALITY", "Confident &middot; Expert &middot; Simple &middot; Bold &middot; Human &middot; Saudi-rooted", "set"], ["CREATIVE EXPRESSION", "Open &mdash; to be developed and pressure-tested", "open"]]} },

    { id:"r-story", type:"read", kicker:"Where we are", q:"The story",
      note:"", view:"story", data:{"text": "Every business starts light. Then it grows, and every step adds another provider: a terminal for the shop, a gateway for online, cards for the team. None of it talks to each other. We spent our careers in Saudi payments and kept seeing good businesses slowed down by their own finances. So we built lite, one licensed platform that connects all of it, so business can keep moving."} }
  ] },

{ id:"B0b", n:"0b", name:"What branding is",
  intro:"Four screens. No questions. They set what the words mean, so the rest of the session is one conversation instead of three.",
  reveal:false, mins:4,
  cards:[
    { id:"r-herbs", type:"read", kicker:"What branding is", q:"Which one is which?",
      note:"", view:"image", data:{"src": "data:image/jpeg;base64,"} },

    { id:"r-words", type:"read", kicker:"What branding is", q:"Three words",
      note:"", view:"words", data:{"words": ["Brand", "Branding", "Brand Identity"], "pub": "Three words used as if they mean the same thing. They do not — and the difference decides what gets made over the next twelve weeks."} },

    { id:"r-cols", type:"read", kicker:"What branding is", q:"Brand vs. brand identity",
      note:"", view:"cols", data:{"head": [["Brand", "Foundation"], ["Identity", "Visual execution"], ["Logo", "Mark / icon"]], "body": [["Emotional response from the customer", "Not singular — a culmination of everything you do", "What your company represents and stands for", "The relationship customers have with you", "Your story, personality, mission, values, vision", "A brand is the result of consistent branding"], ["The tangible, visual elements of your brand:", "· Product / packaging", "· Audio / visual materials", "· Stationery / collateral", "· Flyers, brochures, books", "· Websites / ad creative", "· Apparel / promotional", "· Signage / wayfinding"], ["A mark or icon that identifies your business", "Functions as the face of the business", "An element for customers to remember you by", "Distinguishes you from competitors", "Fosters loyalty over time, when repeated", "Comprises words, imagery and color"]], "pub": "A brand is the result of consistent branding. You cannot design a brand — what you can design is the identity, and the identity is what makes the consistency possible."} },

    { id:"r-today", type:"read", kicker:"What branding is", q:"What today produces",
      note:"", view:"line", data:{"text": "By the end of this session you will have given us a creative brief."} }
  ] },

{ id:"B00", n:"00", name:"Scope",
  intro:"Risk appetite and decision rights. Everything that follows depends on these.",
  reveal:false, mins:3,
  cards:[
    { id:"c-s1", type:"choice", q:"Is this an evolution of the current mark, or a rebuild from zero?",
      note:"This sets the budget and the risk. Everything after it depends on the answer.",
      opts:["Evolution — keep what people recognize", "Rebuild — start clean", "Depends what we see first", "Other ✎"] },

    { id:"c-s2", type:"choice", q:"What has to survive from the current identity?",
      note:"",
      opts:["The name only", "Name + color", "Name + color + mark", "Nothing — all open", "Other ✎"] },

    { id:"c-s4", type:"choice", q:"What must NOT change, no matter what we find today?",
      note:"",
      opts:["The name", "The name in Arabic", "The color", "The arrow in the i", "Nothing is protected", "Other ✎"] },

    { id:"c-s6", type:"choice", q:"What to avoid?",
      note:"",
      opts:["Make it too loud", "Make it too soft", "Make it too Western", "Make it too traditional", "Break something that already works", "Other ✎"] }
  ]},

{ id:"B01", n:"01", name:"Words before pictures",
  intro:"Raw association. Answer with the first thing that comes, before thinking about the business.",
  reveal:false, mins:3,
  cards:[
    { id:"c-v1", type:"choice", q:"What do you SEE when I say Flow?",
      note:"",
      opts:["Water — a river, a current", "A road or a path", "Machinery, gears, a system working", "Light, air, something weightless", "Lines, a trace, movement", "Other ✎"] },

    { id:"c-v2", type:"choice", q:"What do you FEEL when I say Flow?",
      note:"",
      opts:["Calm", "Momentum — pulled forward", "Effortless", "Uninterrupted", "Nothing — it's just a word", "Other ✎"] },

    { id:"c-v3", type:"choice", q:"What do you SEE when I say Lite?",
      note:"",
      opts:["Light — the brightness kind", "Light — the weight kind", "Something small or stripped back", "Lowercase type", "The purple", "Other ✎"] },

    { id:"c-v4", type:"choice", q:"What do you FEEL when I say Lite?",
      note:"",
      opts:["Easy", "Modern", "Approachable", "Unfinished — like a trial version", "Nothing yet", "Other ✎"] }
  ]},

{ id:"B02", n:"02", name:"Position",
  intro:"Where the brand stands before a single shape exists. The first five build on each other.",
  reveal:false, mins:11,
  cards:[
    { id:"c-n4", type:"choice", q:"Where do we sit, and who is NEAREST to us?",
      note:"",
      opts:["A bank-owned player", "A local acquirer", "An international entrant", "A platform like Foodics", "Nobody is near us", "Other ✎"] },

    { id:"c-v11", type:"choice", q:"Name one competitor you must not look like — and why",
      note:"",
      opts:["The market leader", "The one closest to us in size", "The international entrant", "A bank-owned player", "Other ✎"] },

    { id:"c-n1", type:"choice", q:"What do ALL of them say, that we could also say?",
      note:"Everything on this list is a table stake. It can be true and still cannot be your position.",
      opts:["Fast", "Secure", "All-in-one", "Local and licensed", "Built for growth", "Other ✎"] },

    { id:"c-n2", type:"choice", q:"What can NONE of them say?",
      note:"Short list. If it survives the swap test later, it is the whole brand.",
      opts:["One license covering acquiring AND issuing", "Everything on one ledger", "A Saudi team who built this before", "Pricing nobody has to call about", "We do not know yet", "Other ✎"] },

    { id:"c-n3", type:"choice", q:"X-Factor — what makes us radically different?",
      note:"The hardest card. Run the swap test on the answer: could your nearest competitor put this on their site by Thursday?",
      opts:["The licence scope", "The single ledger", "The people", "The speed of onboarding", "The price", "Nothing yet — that is the finding", "Other ✎"] },

    { id:"c-n5", type:"choice", q:"Do we want people to FEEL we are a tech brand, a bank, or a lifestyle brand?",
      note:"Three completely different briefs for type, color and photography. Pick one and the other two become wrong.",
      opts:["A tech brand — infrastructure you install", "A bank — licensed, serious, institutional", "A lifestyle brand — warm, editorial, human", "A tool — quiet, useful, invisible", "A partner — a team, not a product", "Other ✎"] },

    { id:"c-v6", type:"choice", q:"Benefit — how do others feel after interacting with us?",
      note:"",
      opts:["Relieved — one less thing to manage", "In control", "Confident they were not overcharged", "Faster than before", "Taken seriously", "Other ✎"] },

    { id:"c-v7", type:"choice", q:"Community — how would our community describe us, in their words?",
      note:"",
      opts:["\"They actually pick up the phone\"", "\"They're the local ones\"", "\"They're cheaper\"", "\"They're new — we're watching\"", "\"Never heard of them\"", "Other ✎"] },

    { id:"c-v14", type:"choice", q:"The one thing a customer should never feel",
      note:"",
      opts:["Confused", "Small or unimportant", "Sold to", "Slowed down", "Unsure whether it worked", "Patronized", "Other ✎"] },

    { id:"c-v15", type:"choice", q:"Who is this brand NOT for?",
      note:"",
      opts:["People who want cheapest", "People who want hand-holding", "Very large enterprises", "Very small businesses", "Anyone outside our market", "Other ✎"] },

    { id:"c-v12", type:"choice", q:"Name a brand OUTSIDE your category you admire — and exactly what draws you to it",
      note:"",
      opts:["A technology brand", "A luxury or fashion brand", "An airline or hospitality brand", "A local or regional brand", "A sports or automotive brand", "Other ✎"] },

    { id:"r-archetypes", type:"read", kicker:"Reference", q:"The twelve archetypes",
      note:"Read these before you pick. You are choosing one character, not a mood board.", view:"archetypes", data:{"intro": "Archetypes are the personification of behavior. They give a brand a roadmap: one recognizable human character, so every later decision — a color, a photograph, a headline — can be checked against the same person. Two reasons to pick one. Connection: most brands compete on features, benefits and price, which makes them interchangeable. Differentiation: features get copied in a quarter; a personality doesn't.", "items": [["Ruler", "Control, order, authority", "Wants to earn and exercise power. A natural leader: responsible and organized.", "Power isn't everything, it's the only thing.", "Mercedes-Benz · Rolex · Louis Vuitton · Microsoft", "<path d=\"M8 13h32M14 21h20M20 29h8M8 40h32\"/>"], ["Creator", "Innovation, craft, making", "Wants to build things of enduring value. Imaginative, inventive, non-conformist.", "If you can imagine it, it can be done.", "LEGO · Pixar · Adobe · Crayola", "<rect x=\"8\" y=\"14\" width=\"22\" height=\"22\"/><circle cx=\"32\" cy=\"30\" r=\"10\"/>"], ["Sage", "Knowledge, truth, understanding", "Seeks the truth and shares it. Analytical, considered, trusted to be right.", "The truth will set you free.", "Google · BBC · The Economist · Harvard", "<path d=\"M4 24c8-11 32-11 40 0-8 11-32 11-40 0Z\"/><circle cx=\"24\" cy=\"24\" r=\"5\"/>"], ["Innocent", "Safety, simplicity, optimism", "Somewhat naive, seeking happiness. Optimistic, romantic, loyal.", "Free to be you and me.", "Dove · Coca-Cola · Innocent · Charmin", "<circle cx=\"24\" cy=\"24\" r=\"8\"/><path d=\"M24 6v5M24 37v5M6 24h5M37 24h5M11 11l3.5 3.5M33.5 33.5 37 37M37 11l-3.5 3.5M14.5 33.5 11 37\"/>"], ["Explorer", "Freedom, discovery, the frontier", "Restless, independent, drawn to what is out there rather than what is here.", "Don't fence me in.", "Patagonia · Jeep · The North Face · NASA", "<circle cx=\"24\" cy=\"24\" r=\"17\"/><path d=\"m16 32 6-14 10-2-6 14Z\"/>"], ["Outlaw", "Disruption, rule-breaking", "Ready to disrupt and shock. Rebellious and wild.", "Rules are made to be broken.", "Harley-Davidson · Virgin · Diesel", "<path d=\"M6 30h13l5-14 4 14h14\"/><path d=\"M24 6v6M24 38v6\"/>"], ["Magician", "Transformation, making the impossible possible", "Understands the laws of the universe better than anyone, and bends them.", "I make things happen.", "Disney · Tesla · Dyson", "<rect x=\"7\" y=\"15\" width=\"18\" height=\"18\"/><path d=\"M25 15a9 9 0 0 1 0 18\"/><path d=\"M34 12v8M38 16h-8\"/>"], ["Hero", "Mastery, courage, improving the world", "Competent, courageous, bold, confident, inspirational.", "Where there's a will, there's a way.", "Nike · FedEx · BMW · GoPro · Duracell", "<path d=\"M24 6 40 12v13c0 9-7 15-16 18-9-3-16-9-16-18V12Z\"/><path d=\"m16 25 6 6 11-12\"/>"], ["Lover", "Intimacy, passion, connection", "Looking to create a relationship and connect through the senses. Warm, intimate.", "You're the only one.", "Chanel · Alfa Romeo · Victoria's Secret", "<path d=\"M24 38C12 30 8 24 8 18a8 8 0 0 1 16-4 8 8 0 0 1 16 4c0 6-4 12-16 20Z\"/>"], ["Jester", "Pleasure, lightness, the moment", "Lives in the moment, looking to have a good time. Mischievous, light-hearted.", "You only live once.", "Skittles · Old Spice · Dollar Shave Club · Ben & Jerry's", "<path d=\"M5 30c5-16 9 12 14-4s9 12 14-4 5 6 10 4\"/>"], ["Everyman", "Belonging, solid virtues", "Wants to belong and to build solid virtues. Supportive and faithful.", "All are created equal.", "IKEA · Target · Home Depot · eBay", "<rect x=\"5\" y=\"19\" width=\"10\" height=\"10\"/><rect x=\"19\" y=\"19\" width=\"10\" height=\"10\"/><rect x=\"33\" y=\"19\" width=\"10\" height=\"10\"/>"], ["Caregiver", "Service, protection, care", "Wants to be of service, to protect and care for others. Maternal, selfless, compassionate.", "Love your neighbor as yourself.", "Johnson & Johnson · Volvo · UNICEF · Heinz", "<path d=\"M6 24 24 9l18 15\"/><circle cx=\"24\" cy=\"31\" r=\"7\"/>"]], "rule": "One archetype, chosen on purpose, makes every later decision faster. Two makes them slower. Twelve is a mood board."} },

    { id:"c-v8", type:"choice", q:"Primary archetype",
      note:"One archetype, chosen on purpose.",
      opts:["Ruler — Control, order, authority", "Creator — Innovation, craft, making", "Sage — Knowledge, truth, understanding", "Innocent — Safety, simplicity, optimism", "Explorer — Freedom, discovery, the frontier", "Outlaw — Disruption, rule-breaking", "Magician — Transformation, making the impossible possible", "Hero — Mastery, courage, improving the world", "Lover — Intimacy, passion, connection", "Jester — Pleasure, lightness, the moment", "Everyman — Belonging, solid virtues", "Caregiver — Service, protection, care", "None of these fits ✎"] },

    { id:"c-v8b", type:"choice", q:"Secondary archetype",
      note:"One archetype, chosen on purpose.",
      opts:["Ruler — Control, order, authority", "Creator — Innovation, craft, making", "Sage — Knowledge, truth, understanding", "Innocent — Safety, simplicity, optimism", "Explorer — Freedom, discovery, the frontier", "Outlaw — Disruption, rule-breaking", "Magician — Transformation, making the impossible possible", "Hero — Mastery, courage, improving the world", "Lover — Intimacy, passion, connection", "Jester — Pleasure, lightness, the moment", "Everyman — Belonging, solid virtues", "Caregiver — Service, protection, care", "None of these fits ✎"] },

    { id:"c-ic1", type:"choice", q:"What icon do you see when you think about lite?",
      note:"",
      opts:["Feather", "Gravity", "Other ✎"] }
  ]},

{ id:"B02p", n:"02b", name:"Personality",
  intro:"Fourteen pairs. Mark your own first, privately — the axes everyone agrees on take ten seconds; the ones that scatter are the workshop.",
  reveal:true, mins:10,
  cards:[
    { id:"r-sliders", type:"read", kicker:"Reference", q:"How to read the scales",
      note:"", view:"line", data:{"text": "A personality slider puts the brand on a spectrum instead of in a box. Each line is a tension with a well-known brand anchored at either end, so the scale means something concrete rather than abstract. Everyone marks their own first, privately. Then reveal together — the lines you all agree on take ten seconds; the ones that scatter are the workshop."} },

    { id:"c-v9-0", type:"slider", q:"Elite  ↔  Mass appeal", l:"Elite", r:"Mass appeal",
      note:"e.g. Chanel   /   e.g. H&M" },

    { id:"c-v9-1", type:"slider", q:"Serious  ↔  Playful", l:"Serious", r:"Playful",
      note:"e.g. SAP   /   e.g. Google" },

    { id:"c-v9-2", type:"slider", q:"Conventional  ↔  Rebel", l:"Conventional", r:"Rebel",
      note:"e.g. Honda   /   e.g. Tesla" },

    { id:"c-v9-3", type:"slider", q:"Friend  ↔  Authority", l:"Friend", r:"Authority",
      note:"e.g. Cosmopolitan   /   e.g. The New York Times" },

    { id:"c-v9-4", type:"slider", q:"Mature and classic  ↔  Young and innovative", l:"Mature and classic", r:"Young and innovative",
      note:"e.g. HSBC   /   e.g. Revolut" },

    { id:"c-v9-5", type:"slider", q:"Simple  ↔  Complex", l:"Simple", r:"Complex",
      note:"e.g. Apple · Dove   /   e.g. Starbucks · Porsche" },

    { id:"c-v9-6", type:"slider", q:"Youthful  ↔  Established", l:"Youthful", r:"Established",
      note:"e.g. GoPro   /   e.g. Levi's" },

    { id:"c-v9-7", type:"slider", q:"Subtle  ↔  Bright", l:"Subtle", r:"Bright",
      note:"e.g. Sony · Tiffany   /   e.g. M&M's" },

    { id:"c-v9-8", type:"slider", q:"Economical  ↔  Luxury", l:"Economical", r:"Luxury",
      note:"e.g. IKEA   /   e.g. Rolex" },

    { id:"c-v9-9", type:"slider", q:"Unconventional  ↔  Mainstream", l:"Unconventional", r:"Mainstream",
      note:"e.g. Red Bull   /   e.g. Coca-Cola" },

    { id:"c-v9-10", type:"slider", q:"Loud  ↔  Quiet", l:"Loud", r:"Quiet",
      note:"e.g. Harley-Davidson   /   e.g. Rolls-Royce" },

    { id:"c-v9-11", type:"slider", q:"Traditional  ↔  Progressive", l:"Traditional", r:"Progressive",
      note:"e.g. IBM   /   e.g. Airbnb" },

    { id:"c-v9-12", type:"slider", q:"Steady  ↔  Dynamic", l:"Steady", r:"Dynamic",
      note:"e.g. Johnson & Johnson   /   e.g. Samsung" },

    { id:"c-v9-13", type:"slider", q:"Familiar  ↔  Disruptive", l:"Familiar", r:"Disruptive",
      note:"e.g. McDonald's   /   e.g. Netflix" }
  ]},

{ id:"B03", n:"03", name:"Applying Flow",
  intro:"The territory, pressure-tested into something that can be drawn.",
  reveal:false, mins:10,
  cards:[
    { id:"c-f1", type:"choice", q:"Is flow something we SHOW, or something we REMOVE?",
      note:"Two completely different briefs. One produces a visual language of movement. The other produces a visual language of removal — and draws no lines at all.",
      opts:["Draw it — the work literally shows movement: lines, curves, direction", "Prove it — nothing depicts flow; there is simply nothing in the way", "Draw it in the brand, prove it in the product", "Not decided", "Other ✎"] },

    { id:"c-n7", type:"choice", q:"Does flow mean CONNECTS ALL OF IT — and that more is coming until lite controls the whole business?",
      note:"If flow means CONNECTION, the mark has to survive new features being added to it for ten years. That is a structural decision, not a mood.",
      opts:["Yes — flow is the promise of one connected system, and it keeps growing", "Yes, but we cannot say it yet — the features do not exist", "No — flow is about ease, not scope", "No — we stay payments only", "Not decided", "Other ✎"] },

    { id:"c-f2", type:"choice", q:"Flow of what, exactly?",
      note:"Flow is a verb with no object until this is answered.",
      opts:["The money", "The business", "Information — reconciliation, visibility", "The person's attention through the product", "All of it", "Other ✎"] },

    { id:"c-f4", type:"choice", q:"What does friction look like?",
      note:"",
      opts:["Tangle — knots, crossed wires", "Walls — gates, stops, refusals", "Weight — drag, load", "Waiting — a spinner, a queue", "Repetition — doing the same thing four times", "Other ✎"] },

    { id:"c-f10", type:"choice", q:"Does flow have a source and a destination, or is it ambient?",
      note:"",
      opts:["Source and destination — A to B", "Ambient — it is the condition, not the journey", "A network — many to many", "Other ✎"] },

    { id:"c-f11", type:"choice", q:"If flow were ONE LINE, what kind of line?",
      note:"",
      opts:["A smooth curve", "A straight vector", "A path with deliberate turns", "A continuous loop", "A dotted or segmented line", "No line at all", "Other ✎"] },

    { id:"c-f15", type:"choice", q:"Does flow live in the LOGO, or around it?",
      note:"",
      opts:["In the mark itself", "In the system around a static mark", "In motion only", "Recommend to us", "Other ✎"] },

    { id:"c-f20", type:"choice", q:"Which single personality trait does the LOGO carry?",
      note:"",
      opts:["Confident", "Expert", "Simple", "Bold", "Human", "Saudi-rooted", "Other ✎"] },

    { id:"c-f21", type:"choice", q:"When the six traits collide, which goes FIRST?",
      note:"",
      opts:["Bold", "Human", "Saudi-rooted", "Simple", "Expert", "Confident", "Other ✎"] },

    { id:"c-f22", type:"choice", q:"Where does Saudi-rooted actually appear?",
      note:"",
      opts:["In the Arabic letterforms only", "In a motif or pattern", "In the color", "In photography and casting", "Nowhere visible — it is a fact, not a look", "Other ✎"] },

    { id:"c-f23", type:"choice", q:"If we removed the logo entirely, what should still say lite?",
      note:"",
      opts:["The color", "The typography", "A shape or device", "The way information is arranged", "Motion", "Nothing yet — that is the job", "Other ✎"] },

    { id:"c-f26", type:"choice", q:"In one sentence: flow looks like ______",
      note:"",
      opts:["water", "a road", "a circuit", "breath", "a conveyor", "clearing a desk", "Other ✎ — your own", "Nodes"] }
  ]},

{ id:"B04", n:"04", name:"The mark",
  intro:"Seven kinds of mark, and when each one is correct. The word LOGO is hiding four separate decisions.",
  reveal:false, mins:3,
  cards:[
    { id:"c-n6", type:"choice", q:"What is the concept behind the CURRENT logo?",
      note:"",
      opts:["The arrow in the i — movement", "Lowercase = light, easy", "The violet = modern fintech", "There is no concept — it was chosen, not designed", "Nobody here knows", "Other ✎"] },

    { id:"r-logotypes", type:"read", kicker:"Reference", q:"The seven kinds of logo",
      note:"Each one is a different decision about what people have to remember. The examples are live links.", view:"logotypes", data:{"items": [["Wordmark", "The name itself, drawn. No separate symbol.", "The name is short, sayable and worth owning.", "The name is long, generic, or hard to pronounce.", "Stripe · Klarna · Nubank · Tabby · Tamara · lite today", "<svg viewBox=\"0 0 132 46\" class=\"lg\"><rect x=\"30.0\" y=\"19\" width=\"13\" height=\"9\" rx=\"1.5\" fill=\"currentColor\" opacity=\"1\"/><rect x=\"46.5\" y=\"19\" width=\"6\" height=\"9\" rx=\"1.5\" fill=\"currentColor\" opacity=\"1\"/><rect x=\"56.0\" y=\"19\" width=\"6\" height=\"9\" rx=\"1.5\" fill=\"currentColor\" opacity=\"1\"/><rect x=\"65.5\" y=\"19\" width=\"15\" height=\"9\" rx=\"1.5\" fill=\"currentColor\" opacity=\"1\"/></svg>", [["Stripe", "https://stripe.com/"], ["Klarna", "https://www.klarna.com"], ["Nubank", "https://nubank.com.br"], ["Tabby", "https://tabby.ai/"], ["Tamara", "https://tamara.co/"], ["lite — today", "https://lite.sa/"]]], ["Lettermark", "Initials only. A monogram.", "The full name is too long to set at small sizes.", "You have no budget to buy meaning — initials mean nothing until you pay for them.", "HSBC · BNY · most legacy banks", "<svg viewBox=\"0 0 132 46\" class=\"lg\"><rect x=\"44\" y=\"13\" width=\"44\" height=\"21\" rx=\"3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><rect x=\"51\" y=\"19\" width=\"10\" height=\"9\" rx=\"1.5\" fill=\"currentColor\"/><rect x=\"66\" y=\"19\" width=\"12\" height=\"9\" rx=\"1.5\" fill=\"currentColor\"/></svg>", [["HSBC", "https://www.hsbc.com"], ["IBM", "https://www.ibm.com"], ["SAB", "https://www.sab.com"], ["BNY", "https://www.bny.com"]]], ["Symbol", "A picture that stands alone, without the name.", "You need to work with no language at all — or across two scripts.", "You cannot afford the years of pairing it takes before people read it.", "Starling's bird · the Apple · the Nike swoosh", "<svg viewBox=\"0 0 132 46\" class=\"lg\"><path d=\"M66 10a13 13 0 1 0 13 13 9 9 0 0 1-13-13z\" fill=\"currentColor\"/></svg>", [["Starling — the bird", "https://www.starlingbank.com"], ["Nike — the swoosh", "https://www.nike.com"], ["Apple", "https://www.apple.com"], ["Shell", "https://www.shell.com"]]], ["Abstract mark", "A geometric form with no literal referent.", "The business is many things and no single picture covers it.", "You need to be understood fast by people who have never met you.", "Block's cube · Chase's octagon", "<svg viewBox=\"0 0 132 46\" class=\"lg\"><rect x=\"52\" y=\"12\" width=\"14\" height=\"14\" fill=\"currentColor\" opacity=\".45\"/><rect x=\"62\" y=\"20\" width=\"14\" height=\"14\" fill=\"currentColor\" opacity=\".9\"/></svg>", [["Block — the cube", "https://block.xyz"], ["Chase — the octagon", "https://www.chase.com"], ["Adyen", "https://www.adyen.com/"], ["Mastercard", "https://www.mastercard.com"]]], ["Combination", "Name and symbol locked together as one unit.", "You need both, and the symbol has not earned the right to stand alone.", "The lockup is the only way it ever appears — then you have two problems, not one asset.", "Most banks · most of the 170", "<svg viewBox=\"0 0 132 46\" class=\"lg\"><circle cx=\"26\" cy=\"23.5\" r=\"9\" fill=\"currentColor\"/><rect x=\"46.0\" y=\"19\" width=\"12\" height=\"9\" rx=\"1.5\" fill=\"currentColor\" opacity=\"1\"/><rect x=\"61.5\" y=\"19\" width=\"5\" height=\"9\" rx=\"1.5\" fill=\"currentColor\" opacity=\"1\"/><rect x=\"70.0\" y=\"19\" width=\"5\" height=\"9\" rx=\"1.5\" fill=\"currentColor\" opacity=\"1\"/><rect x=\"78.5\" y=\"19\" width=\"13\" height=\"9\" rx=\"1.5\" fill=\"currentColor\" opacity=\"1\"/></svg>", [["Mastercard", "https://www.mastercard.com"], ["Visa", "https://www.visa.com"], ["neoleap", "https://www.neoleap.com.sa/"], ["Foodics", "https://www.foodics.com/"], ["most of the 170", "https://lite.sa/"]]], ["Emblem", "The name sits INSIDE a contained shape. A seal or badge.", "You are claiming heritage, authority, certification.", "You live in app icons and favicons — emblems die small.", "Harley-Davidson · Starbucks · government seals", "<svg viewBox=\"0 0 132 46\" class=\"lg\"><rect x=\"24\" y=\"9\" width=\"84\" height=\"29\" rx=\"14.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><rect x=\"44.0\" y=\"19\" width=\"11\" height=\"9\" rx=\"1.5\" fill=\"currentColor\" opacity=\"1\"/><rect x=\"58.5\" y=\"19\" width=\"5\" height=\"9\" rx=\"1.5\" fill=\"currentColor\" opacity=\"1\"/><rect x=\"67.0\" y=\"19\" width=\"5\" height=\"9\" rx=\"1.5\" fill=\"currentColor\" opacity=\"1\"/><rect x=\"75.5\" y=\"19\" width=\"12\" height=\"9\" rx=\"1.5\" fill=\"currentColor\" opacity=\"1\"/></svg>", [["Starbucks", "https://www.starbucks.com"], ["Harley-Davidson", "https://www.harley-davidson.com"], ["Saudi Central Bank — SAMA", "https://www.sama.gov.sa"], ["most government seals", ""]]], ["Device — not a logo", "A recurring graphic that is NOT part of the lockup.", "You want expression without loading it onto a mark that must work at 16px.", "You have not defined where it may and may not appear — then it is just decoration.", "Stripe's slash · Monzo's outlines · Tabby's Monions · the arrow in lite's i", "<svg viewBox=\"0 0 132 46\" class=\"lg\"><rect x=\"20.0\" y=\"19\" width=\"10\" height=\"9\" rx=\"1.5\" fill=\"currentColor\" opacity=\"1\"/><rect x=\"33.5\" y=\"19\" width=\"5\" height=\"9\" rx=\"1.5\" fill=\"currentColor\" opacity=\"1\"/><rect x=\"42.0\" y=\"19\" width=\"10\" height=\"9\" rx=\"1.5\" fill=\"currentColor\" opacity=\"1\"/><line x1=\"60\" y1=\"23.5\" x2=\"76\" y2=\"23.5\" stroke=\"currentColor\" stroke-width=\"1.2\" stroke-dasharray=\"2.5 2.5\" opacity=\".5\"/><path d=\"M86 12l-8 23\" stroke=\"var(--accent)\" stroke-width=\"4\" stroke-linecap=\"round\"/><text x=\"96\" y=\"27\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" fill=\"currentColor\" opacity=\".55\">free</text></svg>", [["Stripe — the slash", "https://stripe.com/"], ["Monzo — the outlines", "https://monzo.com"], ["Tabby — the Monions", "https://tabby.ai/"], ["Wise — the tapestries", "https://wise.com"], ["lite — the arrow in the i", "https://lite.sa/"]]]]} },

    { id:"c-lg2", type:"choice", q:"Which kind SHOULD it be?",
      note:"",
      opts:["Wordmark only", "Wordmark + a device that can leave the lockup", "Wordmark + a standalone symbol", "Abstract mark", "Emblem", "Other ✎"] },

    { id:"c-m2", type:"choice", q:"Is the logo lower case or upper case — and why?",
      note:"Every lowercase brand hits this in week one and improvises. Rule it now.",
      opts:["Lower case", "Upper case", "Other ✎"] }
  ]},

{ id:"B05", n:"05", name:"Color",
  intro:"The decisions. The full map of what every color means, and who already owns it, is in the reference at the back.",
  reveal:false, mins:6,
  cards:[
    { id:"r-colormap", type:"read", kicker:"Reference", q:"What each color is already saying",
      note:"Measured across 155 fintech brands. Color is the one decision you make against a crowded board, not a blank one.", view:"colormap", data:{"items": [["Blue", "#2563EB", 58, "37%", "Trust, stability, calm, institution.", "The category default. It says WE ARE A BANK AND WE ARE SAFE.", "Nobody — that is the point. 58 brands share it.", "Invisible. You are the fifty-ninth."], ["Navy", "#132A4C", 9, "6%", "Authority, seniority, old money.", "Reads incumbent, not challenger. The color of the thing being disrupted.", "Legacy banks.", "Ages well, but you inherit the incumbent's face."], ["Violet", "#6335EA", 22, "14%", "Modern, technical, deliberately not-a-bank.", "The escape hatch from blue — and everyone escaped to it.", "In KSA: Foodics, Paylink, Tamara, Mala — and lite.", "Six brands sit within one degree of hue. This is where lite is now."], ["Purple", "#820AD1", 3, "2%", "Royal, premium, singular.", "Rare and ownable at the magenta end, far from the violet cluster.", "Nubank owns it globally. SiFi and Pleo locally.", "Nubank's shadow is long — you will be compared."], ["Teal", "#088177", 13, "8%", "Calm, modern, safe.", "The hedge between blue and green. Chosen to avoid, not to claim.", "N26 globally. Hala, Salla, Kashier locally.", "Nobody describes a brand by its teal."], ["Green · money", "#16633D", 11, "7%", "Growth, money, permission.", "Literal. Money-green says money the way a dollar sign does.", "Adyen, neoleap, MNT-Halan.", "Obvious. And it is the Saudi flag color — loaded."], ["Green · signal", "#9FE870", 0, "—", "Energy, GO, tech-forward.", "The bright end. Reads as software, not currency.", "Wise and Tabby have claimed it.", "Already taken by two brands your room knows."], ["Lime", "#D4F22A", 2, "1%", "Loud, signal, unserious on purpose.", "Almost empty lane. Hard to make trustworthy — which is the opportunity.", "Ramp globally. Nearly nobody here.", "Fails as text. Field-and-accent only, forever."], ["Yellow", "#FFE500", 6, "4%", "Optimism, caution, visibility.", "The least-used color in finance because it is the hardest to make trustworthy.", "GoCardless, Fawry, Qonto.", "Cannot be type. Handled well it reads as competence."], ["Orange", "#F26A1B", 15, "10%", "Energy, approachability, value.", "Common across MENA — reads telecom, discount, delivery.", "Geidea, HyperPay, Amazon Payment Services.", "Cheap unless the craft is very high."], ["Red", "#E23434", 9, "6%", "Urgency, appetite, alarm.", "Dangerous in payments: red is the color of decline, overdraft and error.", "Ottu, e-finance, Sympl. Monzo's coral sits just off it.", "Your own product UI will fight your brand."], ["Pink", "#FFA8CD", 3, "2%", "Appetite, pleasure, non-institutional.", "Turns a money product into a feeling. Almost nobody dares in B2B.", "Klarna in BNPL. Rapyd, Pomelo.", "Will a Saudi enterprise buyer defend it in a board meeting?"], ["Black", "#16120E", 13, "8%", "Restraint, premium, architecture.", "The parent-brand color — it lets everything else be loud.", "Block, Tabby, Lean, Pluto.", "Needs a second color to live. Alone it is a void."], ["Sand · earth", "#B19662", 1, "1%", "Ground, material, place, warmth.", "Effectively empty. One brand of 155 uses it as a primary.", "Qashio, and nobody else.", "Untested in payments — which is the whole argument for and against it."]]} },

    { id:"c-x1", type:"choice", q:"Do we claim to be a NEW system, or a better version of what exists?",
      note:"",
      opts:["A new system — we replace the mess", "A better version — the same thing, done well", "Both, depending who is asking", "Other ✎"] },

    { id:"c-x3", type:"choice", q:"Do we want to OWN one color completely?",
      note:"",
      opts:["Yes — total ownership", "No — a system, not a color", "Only if the color is free", "Other ✎"] },

    { id:"c-k2", type:"choice", q:"Which colors are FORBIDDEN for lite — and why?",
      note:"",
      opts:["Blue — it contradicts the claim", "Red — it is the color of a declined payment", "Flag green — too literal for a Saudi-rooted brand", "Nothing is forbidden", "Other ✎"] },

    { id:"c-k3", type:"choice", q:"Does Saudi-rooted mean a Saudi color?",
      note:"",
      opts:["Yes — green, from the flag", "Yes — sand, stone, earth", "Yes — gold", "No — Saudi-rooted is a behavior, not a hue", "We have not decided", "Other ✎"] },

    { id:"c-x5", type:"choice", q:"Where does lite's boldness live — color, type, or layout?",
      note:"",
      opts:["Color", "Type", "Layout / composition", "Motion", "Photography", "Other ✎"] },

    { id:"c-x8", type:"choice", q:"Instant recognition, or still right in ten years?",
      note:"",
      opts:["Recognition — be seen now", "Longevity — age well", "Recognition now, review in 5 years", "Other ✎"] },

    { id:"c-c8", type:"choice", q:"Does color carry meaning in the product?",
      note:"",
      opts:["Yes — error/warning/success reserved", "Partly", "No", "Product not built yet", "Other ✎"] }
  ]},

{ id:"B06", n:"06", name:"Type & script",
  intro:"Two scripts, one voice. The most expensive block to get wrong, and the cheapest to decide today.",
  reveal:false, mins:3,
  cards:[
    { id:"c-t2", type:"choice", q:"Which script is the master?",
      note:"The master script is the one drawn first. The other is adapted to it. Most bilingual marks fail here.",
      opts:["Arabic", "Latin", "Equal — designed together", "Not settled", "Other ✎"] },

    { id:"c-t7", type:"choice", q:"Numerals",
      note:"One decision for the entire system. Mixed numerals inside one interface is the most visible sign that nobody decided.",
      opts:["Arabic-Indic (١٢٣) everywhere", "Western (123) everywhere", "Western in product, Arabic-Indic in marketing", "Not decided", "Other ✎"] },

    { id:"c-t8", type:"choice", q:"How do we address the reader?",
      note:"Formality is the fastest way to signal which market you actually belong to.",
      opts:["أنت — direct and singular", "أنتم — formal and plural", "Direct with merchants, formal with institutions", "Other ✎"] }
  ]},

{ id:"B07", n:"07", name:"Assets, layout & motion",
  intro:"Everything that is not the logo — which is where a brand actually lives.",
  reveal:false, mins:3,
  cards:[
    { id:"c-g3", type:"choice", q:"From ten meters, before reading a word — what should someone be able to tell?",
      note:"Before reading a word. This is the only test an ad on a highway has to pass.",
      opts:["Serious and established", "Modern and technical", "Warm and human", "Premium", "Locally rooted", "Other ✎"] },

    { id:"c-a3", type:"choice", q:"If the brand walked into a client meeting — who walks in?",
      note:"What are they wearing, what is the first thing they say, and what would they never say?",
      opts:["A senior banker in a suit", "A young founder in a polo shirt", "An engineer — the smartest person in the room", "A trusted operator who has done this before", "A consultant with a deck", "Other ✎"] },

    { id:"c-p1", type:"choice", q:"Do people appear in lite's photography?",
      note:"",
      opts:["Yes — merchants and their shops", "Yes — hands and details only", "No people — product only", "No photography at all", "Not decided", "Other ✎"] }
  ]},

{ id:"B08", n:"08", name:"Reference",
  intro:"Nine brands and the decision behind each one. Keep it for after the session — nothing here needs answering.",
  reveal:false, mins:6,
  cards:[
    { id:"r-cases", type:"read", kicker:"Reference", q:"How other brands decided",
      note:"Every line is a Why and its answer. The last line in each is the question it puts to lite.", view:"cases", data:{"items": [["Stripe", "#635BFF", "the one blue", "Acquiring · US", [["Why does it exist?", "Built for the developer who installs it, not the executive who signs for it."], ["Why violet, not blue?", "Blue reads BANK. One step off still reads payments and stops reading bank."], ["Why no symbol beside the name?", "A symbol implies a company you meet. A wordmark implies a thing you install."], ["Then isn't the slash a symbol?", "Fair — it is a mark. But it never sits beside the name: it is a device inside layouts and the app icon, never a lockup."], ["Why a slash, of all shapes?", "It is syntax. Their audience reads / in code and URLs every day."], ["Why lowercase?", "Infrastructure, not an institution. Capitals would claim authority they do not want."], ["Why is the color only a background?", "The mark must survive on a white terminal, so the warmth goes behind it."], ["Why does it work?", "The gradient carries the personality so the mark can stay severe."]], "Is lite in the blue family?", "If yes, we are drawing inside Stripe's box with none of its head start.", "<svg viewBox=\"0 0 240 104\" class=\"dg\"><rect x=\"6\" y=\"14\" width=\"228\" height=\"38\" rx=\"3\" fill=\"#635BFF\" opacity=\".92\"/><text x=\"6\" y=\"10\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">EXPRESSIVE LAYER — CARRIES ALL WARMTH</text><rect x=\"6\" y=\"70\" width=\"78\" height=\"12\" rx=\"1\" fill=\"currentColor\"/><text x=\"6\" y=\"66\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">THE MARK — STAYS SEVERE</text><text x=\"92\" y=\"80\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">NEVER THE SAME JOB</text></svg>", "https://stripe.com/"], ["Wise", "#9FE870", "citrus green", "Cross-border · UK", [["Why does it exist?", "It refused the bank frame — not a cheaper bank, a different system."], ["So why no blue?", "You cannot claim to be a new system while dressed as the old one."], ["Why citrus green?", "Money in one glance, GO in the other — and the card was already green."], ["Why a flag?", "The product's problem is borders. A flag means A COUNTRY in every country."], ["Why an arrow as well?", "Country + direction = money crossing a border. One shape, both halves of the product."], ["Why keep the old mark?", "Replacing a recognized mark spends recognition to buy novelty."], ["Why redraw it on a grid?", "Stroke area equals counter area, so it survives at 16px."], ["Why does the logo do so little?", "Expression moved into the color tapestries. The logo only has to work small."]], "What is lite's border?", "Wise named the one obstacle it removes. lite's is the gap between providers — so name the shape for THE GAP CLOSED.", "<svg viewBox=\"0 0 240 104\" class=\"dg\"><g stroke=\"currentColor\" stroke-opacity=\".16\" stroke-width=\"1\"><path d=\"M6 14V90\"/><path d=\"M22 14V90\"/><path d=\"M38 14V90\"/><path d=\"M54 14V90\"/><path d=\"M70 14V90\"/><path d=\"M86 14V90\"/><path d=\"M102 14V90\"/><path d=\"M118 14V90\"/><path d=\"M134 14V90\"/><path d=\"M150 14V90\"/><path d=\"M166 14V90\"/><path d=\"M182 14V90\"/><path d=\"M198 14V90\"/><path d=\"M214 14V90\"/><path d=\"M230 14V90\"/><path d=\"M6 14H234\"/><path d=\"M6 52H234\"/><path d=\"M6 90H234\"/></g><rect x=\"38\" y=\"30\" width=\"44\" height=\"44\" fill=\"#9FE870\"/><rect x=\"102\" y=\"30\" width=\"44\" height=\"44\" fill=\"none\" stroke=\"#9FE870\" stroke-width=\"11\"/><text x=\"38\" y=\"24\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">STROKE</text><text x=\"102\" y=\"24\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">COUNTER — EQUAL AREA</text><text x=\"6\" y=\"100\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">SURVIVES AT 16PX AND FOR LOW VISION</text></svg>", "https://wise.com"], ["Nubank", "#820AD1", "purple", "Digital bank · Brazil", [["Why does it exist?", "Positioned as the opposite of a bank, not a better one."], ["Why purple?", "No bank in Brazil owned it. A land grab, not a mood."], ["Why is BANK missing from the mark?", "You cannot be the opposite of a bank with the word inside your logo."], ["Why curves?", "The loop already lives between the n and the u. They used what the name gave them."], ["Why lowercase?", "Sentence case reads like a person. Capitals read like an institution."], ["Why modular?", "So content can sit inside the mark at any size — banner, card, favicon."], ["Why does it work?", "Staff use the color as the company's name."]], "Is any color still unowned in Saudi payments?", "Owning one beats a clever system nobody remembers — but it is a one-way door.", "<svg viewBox=\"0 0 240 104\" class=\"dg\"><rect x=\"6\" y=\"22\" width=\"96\" height=\"60\" rx=\"30\" fill=\"#820AD1\"/><rect x=\"26\" y=\"44\" width=\"56\" height=\"16\" rx=\"8\" fill=\"#FFF\" opacity=\".9\"/><rect x=\"116\" y=\"38\" width=\"58\" height=\"34\" rx=\"17\" fill=\"#820AD1\"/><rect x=\"128\" y=\"50\" width=\"34\" height=\"10\" rx=\"5\" fill=\"#FFF\" opacity=\".9\"/><rect x=\"188\" y=\"46\" width=\"34\" height=\"18\" rx=\"9\" fill=\"#820AD1\"/><rect x=\"195\" y=\"52\" width=\"20\" height=\"6\" rx=\"3\" fill=\"#FFF\" opacity=\".9\"/><text x=\"6\" y=\"16\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">ONE MODULAR MARK — CONTENT SITS INSIDE AT ANY SCALE</text><text x=\"6\" y=\"98\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">BANNER &#8594; CARD &#8594; FAVICON</text></svg>", "https://nubank.com.br"], ["Monzo", "#FF4F40", "hot coral", "Digital bank · UK", [["Why does it exist?", "A bank that behaves like a person you would text."], ["Why coral and not red?", "Red is alarm, debt, decline. Coral is warm — same volume, opposite feeling."], ["Why that loud at all?", "It was a card color. It had to be spotted in a wallet and across a bar table."], ["Why not capital letters?", "A capital wordmark is a bank. Lowercase is a name a friend uses."], ["Why leave the logo alone?", "The distinctive asset was never the logo. It was the card."], ["Why outlines instead of fills?", "A coral fill fights photography. An outline frames it."], ["Why does it work?", "People recognized the card first. The identity was built to catch up."]], "What does lite's customer already recognize?", "Look at the terminal, the card and the dashboard before drawing anything.", "<svg viewBox=\"0 0 240 104\" class=\"dg\"><rect x=\"6\" y=\"18\" width=\"130\" height=\"80\" rx=\"6\" fill=\"#FF4F40\"/><rect x=\"18\" y=\"74\" width=\"40\" height=\"8\" rx=\"2\" fill=\"#FFF\" opacity=\".55\"/><text x=\"6\" y=\"12\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">THE PRIMARY ASSET</text><rect x=\"160\" y=\"50\" width=\"54\" height=\"10\" rx=\"1\" fill=\"currentColor\" opacity=\".55\"/><text x=\"160\" y=\"44\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">THE LOGO</text><text x=\"160\" y=\"76\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">LEFT ALONE</text></svg>", "https://monzo.com"], ["GoCardless", "#FFE500", "yellow", "Bank debit · UK", [["Why does it exist?", "It takes a side: bank payments beat cards."], ["Why yellow?", "The least-used color in finance, because it is the hardest to make look trustworthy."], ["Why can it never be type?", "Yellow fails contrast on white at any weight. So: field and accent only."], ["Why a symbol, when Stripe refused one?", "Square avatars. A wordmark cannot fill one."], ["Why two shapes — roundel and tile?", "One for round slots, one for square. The container decided the form."], ["Why a gradient inside it?", "The only way that yellow holds an edge on a light background."], ["Why does it work?", "A hard color forced a rigorous system. A safe one would not have."]], "Would lite accept a color that costs it something?", "A hard color handled well reads as competence. A safe color handled well reads as nothing.", "<svg viewBox=\"0 0 240 104\" class=\"dg\"><rect x=\"6\" y=\"16\" width=\"108\" height=\"58\" rx=\"3\" fill=\"#FFE500\"/><rect x=\"20\" y=\"38\" width=\"80\" height=\"12\" rx=\"1\" fill=\"#16120E\"/><text x=\"6\" y=\"88\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">FIELD + DARK TYPE &#10003;</text><rect x=\"128\" y=\"16\" width=\"106\" height=\"58\" rx=\"3\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".25\"/><rect x=\"142\" y=\"38\" width=\"80\" height=\"12\" rx=\"1\" fill=\"#FFE500\"/><text x=\"128\" y=\"88\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">YELLOW AS TYPE &#10007;</text><text x=\"6\" y=\"100\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">THE CONSTRAINT MADE THE SYSTEM</text></svg>", "https://gocardless.com/"], ["Klarna", "#FFA8CD", "pink", "BNPL · Sweden", [["Why does it exist?", "Paying framed as an emotional moment, not a rational one."], ["Why pink?", "Every lending brand signals seriousness. Pink signals appetite."], ["Why is everything else plain?", "Pink is already the voice. A second loud element would kill it."], ["Why lowercase?", "A companion at checkout, not the institution behind it."], ["Why keep the circle in the 2024 redraw?", "Keeping the old rule made it read as maintenance, not panic."], ["Why does it work?", "One loud thing, chosen on purpose."]], "If lite goes loud on color, does everything else go quiet?", "You get one loud element. Choose it before the palette is signed off.", "<svg viewBox=\"0 0 240 104\" class=\"dg\"><rect x=\"6\" y=\"16\" width=\"96\" height=\"72\" rx=\"3\" fill=\"#FFA8CD\"/><g stroke=\"currentColor\" stroke-opacity=\".3\" stroke-width=\"2\"><path d=\"M118 26h108\"/><path d=\"M118 38h108\"/><path d=\"M118 50h72\"/><path d=\"M118 62h108\"/><path d=\"M118 74h48\"/></g><text x=\"6\" y=\"10\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">ONE LOUD THING</text><text x=\"118\" y=\"10\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">EVERYTHING ELSE QUIET</text><text x=\"6\" y=\"100\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">REVERSE THE RATIO AND IT COLLAPSES</text></svg>", "https://www.klarna.com"], ["N26", "#088177", "teal", "Digital bank · Germany", [["Why does it exist?", "A bank that looks like a lifestyle brand."], ["Why teal?", "To avoid committing to blue or green. The most deliberate hedge here."], ["Why is that a warning?", "Nobody describes N26 by its color. That is what a hedge buys you."], ["So why does it still work?", "The restraint — editorial layouts, space, photography. Not the teal."], ["Why looser letter-spacing?", "The whole category tightens. They opened it, where nobody looks."], ["Why admit the old mark was characterless?", "Saying it out loud is what earned permission to redraw it."]], "Is lite's color chosen for what it avoids, or what it claims?", "NOT TOO BLUE is not a decision yet.", "<svg viewBox=\"0 0 240 104\" class=\"dg\"><defs><linearGradient id=\"n26g\" x1=\"0\" x2=\"1\"><stop offset=\"0\" stop-color=\"#0070E0\"/><stop offset=\"1\" stop-color=\"#00D16A\"/></linearGradient></defs><rect x=\"6\" y=\"40\" width=\"228\" height=\"20\" rx=\"3\" fill=\"url(#n26g)\" opacity=\".85\"/><path d=\"M120 32V68\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"120\" cy=\"50\" r=\"7\" fill=\"#088177\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"6\" y=\"30\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">TRUST / BLUE</text><text x=\"182\" y=\"30\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">MONEY / GREEN</text><text x=\"6\" y=\"84\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">THE HEDGE — SAFE, AND HARD TO OWN</text></svg>", "https://n26.com"], ["Starling", "#321E37", "aubergine", "Digital bank · UK", [["Why does it exist?", "Good with money — a customer capability, not a product feature."], ["Why near-black aubergine?", "Every challenger went bright. Dark was the open move, and it reads adult."], ["Why a ground and not an accent?", "A dark primary is a stage. Every other color works on top of it."], ["Why keep the bird?", "It is the one thing a customer could draw from memory."], ["Why does it work?", "It is nearly a neutral, so it ages better than a signature bright."]], "Does lite want flexibility or recognition?", "A dark primary buys longevity and costs recognition. You cannot have both.", "<svg viewBox=\"0 0 240 104\" class=\"dg\"><rect x=\"6\" y=\"14\" width=\"228\" height=\"62\" rx=\"3\" fill=\"#321E37\"/><rect x=\"22\" y=\"34\" width=\"34\" height=\"22\" rx=\"2\" fill=\"#FF4F40\"/><rect x=\"70\" y=\"34\" width=\"34\" height=\"22\" rx=\"2\" fill=\"#FFE500\"/><rect x=\"118\" y=\"34\" width=\"34\" height=\"22\" rx=\"2\" fill=\"#9FE870\"/><rect x=\"166\" y=\"34\" width=\"34\" height=\"22\" rx=\"2\" fill=\"#FFA8CD\"/><text x=\"6\" y=\"90\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">A NEUTRAL PRIMARY — EVERY ACCENT WORKS ON IT</text></svg>", "https://www.starlingbank.com"], ["Block", "#000000", "no color at all", "Group brand · US", [["Why does it exist?", "One name holding many meanings — building block, city block, blockchain, code block, obstacle."], ["Why black?", "The parent must not compete with Square, Cash App and Tidal."], ["Why a cube of stacked squares?", "Each square is one business. Together they read as one company."], ["Why capitals here?", "A parent company signs contracts. This is the one place authority is the point."], ["Why is the animated version primary?", "They mandated motion over static. The still logo is the fallback."], ["Why does it work?", "Brand architecture expressed as restraint."]], "Will lite ever hold sub-brands?", "If yes, the master brand does not get to shout — and that is decided now, not later.", "<svg viewBox=\"0 0 240 104\" class=\"dg\"><rect x=\"6\" y=\"26\" width=\"64\" height=\"64\" rx=\"4\" fill=\"#111112\"/><text x=\"6\" y=\"20\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">PARENT — SILENT</text><rect x=\"92\" y=\"34\" width=\"40\" height=\"40\" rx=\"4\" fill=\"#00E013\"/><rect x=\"146\" y=\"34\" width=\"40\" height=\"40\" rx=\"4\" fill=\"#0070E0\"/><rect x=\"200\" y=\"34\" width=\"34\" height=\"40\" rx=\"4\" fill=\"#FF4F40\"/><text x=\"92\" y=\"24\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">CHILDREN — LOUD</text><text x=\"6\" y=\"102\" font-family=\"IBM Plex Mono, monospace\" font-size=\"7\" letter-spacing=\"1\" fill=\"currentColor\" opacity=\".62\">ARCHITECTURE EXPRESSED AS RESTRAINT</text></svg>", "https://block.xyz"]]} }
  ] }

];
